package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

public class SimpleType_construct_TriageGen2Test {

    @Test
    public void testConstruct_WithValidClass() {
        // Test with a standard non-container, non-array class
        Class<?> testClass = String.class;
        SimpleType result = SimpleType.construct(testClass);

        assertNotNull(result);
        assertEquals(testClass, result.getRawClass());
    }

    @Test
    public void testConstruct_WithIntegerClass() {
        // Test with a primitive wrapper
        Class<?> testClass = Integer.class;
        SimpleType result = SimpleType.construct(testClass);

        assertNotNull(result);
        assertEquals(testClass, result.getRawClass());
    }

    @Test
    public void testConstruct_WithMapThrowsException() {
        // Test Map branch coverage
        Class<?> mapClass = HashMap.class;
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(mapClass);
        });

        assertEquals("Can not construct SimpleType for a Map (class: java.util.HashMap)", exception.getMessage());
    }

    @Test
    public void testConstruct_WithMapInterfaceThrowsException() {
        // Test Map interface branch coverage
        Class<?> mapInterface = Map.class;
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(mapInterface);
        });

        assertEquals("Can not construct SimpleType for a Map (class: java.util.Map)", exception.getMessage());
    }

    @Test
    public void testConstruct_WithCollectionThrowsException() {
        // Test Collection branch coverage
        Class<?> collectionClass = ArrayList.class;
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(collectionClass);
        });

        assertEquals("Can not construct SimpleType for a Collection (class: java.util.ArrayList)", exception.getMessage());
    }

    @Test
    public void testConstruct_WithCollectionInterfaceThrowsException() {
        // Test Collection interface branch coverage
        Class<?> collectionInterface = List.class;
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(collectionInterface);
        });

        assertEquals("Can not construct SimpleType for a Collection (class: java.util.List)", exception.getMessage());
    }

    @Test
    public void testConstruct_WithArrayThrowsException() {
        // Test Array branch coverage
        Class<?> arrayClass = String[].class;
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(arrayClass);
        });

        assertEquals("Can not construct SimpleType for an array (class: [Ljava.lang.String;)", exception.getMessage());
    }

    @Test
    public void testConstruct_WithPrimitiveArrayThrowsException() {
        // Test primitive array branch coverage
        Class<?> primitiveArray = int[].class;
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(primitiveArray);
        });

        assertEquals("Can not construct SimpleType for an array (class: [I)", exception.getMessage());
    }
}
